do $$ declare t text; p text; begin foreach t in array array['departments','employees','training_courses','learning_materials','question_banks','import_jobs','questions','question_options','exams','exam_bank_rules','training_batches','batch_bank_rules','batch_employees','employee_material_progress','exam_attempts','attempt_questions','attempt_question_options','attempt_answers'] loop execute format('alter table %I enable row level security',t); p:='authenticated_admin_all_'||t; execute format('drop policy if exists %I on %I',p,t); execute format('create policy %I on %I for all to authenticated using (true) with check (true)',p,t); execute format('revoke all on table %I from anon',t); end loop; end $$;
